INSERT INTO player_status VALUES(241,56,'2026-09-13','suspension','Red card suspension (3 matches)','08-23 브라이튼전 폭력행위 퇴장 3경기 — 09-12 포레스트전이 마지막 결장, 09-16 코번트리전 복귀 예정','2026-08-23','웹 수집 2026-09-13(서브에이전트 /tmp/injuries_4teams.md) — 에메리 09-12 경기 후 회견 인용(Yahoo Sports·Sports Mole) · ⚠️ 집계 사이트(FotMob)가 아직 반영하지 않은 신규 건이라 같은 날 FotMob 스냅샷에는 없다','⚠️ 스냅샷이다 — pulled 시점 상태이고 복귀 예상은 소스 추정이다. 등급 B(감독 발언 인용 보도). 구단 공식 발표는 아직 없다 — 다음 회차에 avfc.co.uk·FotMob 재확인 필요.');
INSERT INTO player_status VALUES(242,6,'2026-09-14','injury','Ankle injury','결장 기간 추정 **6~8주** — 1874 팟캐스트 진행자 서술(「with Maatsen''s injury six to eight weeks … Villa need to keep Ruggeri fit for that period」, 마첸 부상 6~8주 — 그 기간 동안 루제리를 건강하게 유지해야 한다). 09-13 스냅샷(status #239)의 에메리 「maybe it is a long time」을 구체화하는 값이다.','2026-09-14','서사(AVL·D+2): 1874 「5 Things We Learned From Forest Defeat」(TEWTwrP1aAI, 2026-09-14) [28:21] 전사 reports/transcripts/TEWTwrP1aAI.en.md','⚠️ 스냅샷이다. 등급 C — **3티어 팬 채널 진행자의 추정치이며 구단·감독 1차 발표가 아니다.** 구단 공식·FotMob 반영은 미확인. ⚠️ auto-caption. 09-13 스냅샷(#239)을 대체하지 않고 병존한다.');
INSERT INTO player_status VALUES(243,4,'2026-09-14','injury','Hamstring injury','결장 기간 추정 **약 4주(그중 3주는 A매치 휴식기)** — 1874 진행자 서술(「hamstring, he''ll be out for four weeks you suspect but three of those weeks will be international break. So not completely the end of the world」, 햄스트링이라 4주 결장으로 짐작되지만 그중 3주는 A매치 휴식기라 완전한 재앙은 아니다). 09-13 스냅샷(status #240)의 「기간 미제시」를 구체화한다.','2026-09-14','서사(AVL·D+2): 1874 매치 리액션(HtPgFuvPe6Q, 2026-09-12) [06:09] 전사 reports/transcripts/HtPgFuvPe6Q.en.md','⚠️ 스냅샷이다. 등급 C — **3티어 팬 채널 진행자의 추정치**(「you suspect」로 스스로 추정임을 밝혔다). 구단 공식 발표 아님. ⚠️ auto-caption. 09-13 스냅샷(#240)을 대체하지 않고 병존한다.');
INSERT INTO player_status VALUES(244,19,'2026-09-17','injury','Back injury','에메리 「hopefully its not a big injury」(「큰 부상이 아니길 바란다」) — 기간 미제시','2026-09-16','웹 수집 2026-09-17 match-watch 회차 — 에메리 경기 후 1차 발언(PA·VAVEL·Sky) / 시메오네 D-1 회견 + EFE 「Sin Julián Álvarez ni Alexander Sørloth, lesionados」(「훌리안 알바레스도 알렉산더 쇠를로트도 없이 — 부상」)','⚠️ 스냅샷이다 — pulled 시점 상태이고 복귀 예상은 소스 추정이다. 등급 B(감독 발언·통신사 인용). 구단 공식 발표는 아직 없다.');
INSERT INTO player_status VALUES(245,172,'2026-09-17','injury','Injury (부위 미특정)','시메오네 D-1 회견에서 결장 확정(회복 과정 중). EFE가 「lesionados」로 독립 기재. ⚠️ 부위·「근육」 여부는 어떤 소스도 특정하지 않았다','2026-09-15','웹 수집 2026-09-17 match-watch 회차 — 에메리 경기 후 1차 발언(PA·VAVEL·Sky) / 시메오네 D-1 회견 + EFE 「Sin Julián Álvarez ni Alexander Sørloth, lesionados」(「훌리안 알바레스도 알렉산더 쇠를로트도 없이 — 부상」)','⚠️ 스냅샷이다 — pulled 시점 상태이고 복귀 예상은 소스 추정이다. 등급 B(감독 발언·통신사 인용). 구단 공식 발표는 아직 없다.');
INSERT INTO player_status VALUES(246,210,'2026-09-18','injury','Wrist injury','Doubtful','2026-08-04','fotmob.com/api/data (player 156008, Playwright 직접 조회, 2026-09-18 수집)','⚠️ 스냅샷이다 — pulled 시점의 상태이고 복귀 예상은 소스 추정이다. 부상은 이적 등급을 바꾸지 않는다(obs#272) — 성사 확률·구조 비용 축이다. ⭐ 변화: 09-13 스냅샷의 복귀 예상 「September 2026」이 사라지고 expectedReturnDateParam=null·fallback=Doubtful로 바뀌었다(복귀 지연 신호). as_of(2026-08-04)는 소스의 lastUpdated로 동일.');
INSERT INTO player_status VALUES(247,19,'2026-09-18','injury','Back injury (하지 절뚝임 동반)','에메리 D+2 「Of course, it''s not my expectation a big injury.」(물론 큰 부상일 거라 예상하진 않는다.) — **기간·검사결과·복귀시점 여전히 미제시**. 현장 기록은 「hobbling off at half time」(하프타임에 절뚝이며 나감)으로 하지 증상을 적어 「등」 서술과 갈린다. 09-19 스퍼스전 doubt(캐시·고메스·마조와 함께).','2026-09-17','웹 수집 2026-09-18 D+2 회차 — Read Aston Villa 2026-09-17(에메리 추가 발언) · Tanswell Bluesky 실시간 T19:51 · footballchannel.jp 2026-09-17(The Athletic 인용). obs#847','MEDIUM — 구단 공식 진단 없음. 부위 서술 불일치(등 ↔ 절뚝임) 미해소, D+3 재시도 대상.');
INSERT INTO player_status VALUES(248,56,'2026-09-18','injury','Calf discomfort','09-16 코번트리전 결장 사유 — ⛔ **징계가 아니다**(3경기 PL 징계는 09-12 포레스트전으로 종료). 에메리 「If it''s going well, he might be available for Saturday. It is uncertain for now.」(잘 풀리면 토요일에 가용할 수도 있다. 지금은 불확실하다) — 목·금 상태 점검 후 09-19 스퍼스전 판단.','2026-09-17','웹 수집 2026-09-18 D+2 회차 — Yahoo Sports 2026-09-16 「The Brazilian is experiencing some ''discomfort''」(브라질 선수가 「불편」을 겪고 있다) · 에메리 스퍼스 D-1 회견(Read Aston Villa 2026-09-17 전재). obs#840','MEDIUM-HIGH — 구단 공식 성명이 아니라 매체·회견 기반. obs#812의 「징계 결장」 전제를 정정한다.');
INSERT INTO player_status VALUES(249,56,'2026-09-18','suspension','Red card suspension (3 matches) — SERVED','⛔ **범위 확정: 「프리미어리그 3경기」이지 공식전이 아니다.** 아스날·헐·포레스트에 적용돼 **09-12 포레스트전으로 종료**. 직접 증거: 징계 기간 중 **CL 브뤼헤전 선발 출전**. obs#812의 「코번트리전도 징계 결장」은 틀렸다 — 그 결장은 종아리 불편이다.','2026-09-12','웹 수집 2026-09-18 D+2 회차 — Read Aston Villa 2026-09-13 「ban ends before Coventry」(코번트리전 전에 징계가 끝난다) · CL 브뤼헤전 선발 기록. obs#840 (obs#241의 열린 범위 판정을 닫는 새 스냅샷 — 기존 행은 보존)','HIGH — CL 출전이 범위의 직접 증거.');
INSERT INTO player_status VALUES(250,172,'2026-09-18','injury','근육 과부하(sobrecarga) — 리버풀전 · 부위 미특정','09-18 훈련 정상 소화, 더비(09-20) 출전 가능. ⚠️ Marca 「uno más」(정상 전력) ↔ AS 「vuelta parcial」·「no a lo mejor como titular」(선발은 아닐 수 있음)로 매체 온도차. 결장 2경기(레알 소시에다드·오사수나)','2026-09-18','AS(Patricia Cazón 2026-09-18) 「una pequeña sobrecarga en el partido… ante el Liverpool」(「리버풀전에서 입은 경미한 근육 과부하」) / Marca(David G. Medina 2026-09-18) 「ya es uno más… salvo algún contratiempo de última hora」(「이미 한 명의 정상 전력… 막판 변수가 없는 한」). D+2 브라우저 직접 수집.','⚠️ 스냅샷이다 — pulled 시점 상태다. 등급 B(전국지 2매체, 구단 공식 발표 아님). obs#824의 「부위·근육 여부 미특정」을 **유형까지만** 해소한다(부위는 여전히 미특정). ⛔ 기존 행 245는 그대로 둔다.');
INSERT INTO player_status VALUES(251,173,'2026-09-18','injury','소실근(sóleo) 부상 — 구단은 「contractura」로 발표','1개월 이상 결장, 더비 불가. 09-18 훈련 불참. ⭐ 구단 발표(근육 뭉침)와 실제 진단(소실근 부상)이 다르다는 보도 — 09-13 FotMob 스냅샷의 「Muscle injury / September 2026」보다 길다','2026-09-18','AS(Patricia Cazón 2026-09-18) 「siga faltando Sorloth, **más de un mes de baja** aunque con buena evolución de esa **contractura que dijo el club y que en realidad era una lesión en el sóleo**」(「쇠를로트는 계속 빠진다 — **한 달 이상 결장**이고, 구단이 말한 **근육 뭉침, 실제로는 소실근 부상**은 경과가 좋긴 하다」) / Marca(2026-09-18) 바리오스·쇠를로트 훈련 불참·근육 부상 기재. D+2 브라우저 직접 수집.','⚠️ 스냅샷이다. 등급 B(매체 단독 진단 정정 보도 — 구단 공식과 불일치를 명시). ⛔ 기존 행 235는 그대로 둔다.');
INSERT INTO player_status VALUES(252,155,'2026-09-18','injury','근육 부상(muscular)','09-18 훈련 불참, 더비(09-20) 사실상 불가. ⚠️ 09-13 FotMob 스냅샷은 「About 1-2 weeks」였는데 09-18까지 미복귀 — 예상보다 길어지고 있다. 카르도소가 그 자리를 메우고 있다(AS 「Sin Barrios… el socio perfecto para Koke」)','2026-09-18','Marca(David G. Medina 2026-09-18) 「Los que no se han ejercitado… **Barrios y Sorloth. Ambos con lesiones musculares y ambos sin opciones casi de llegar al derbi**」(「훈련하지 않은 이들은 **바리오스와 쇠를로트다. 둘 다 근육 부상이고 둘 다 더비에 맞출 가능성이 거의 없다**」). D+2 브라우저 직접 수집.','⚠️ 스냅샷이다. 등급 B(전국지). ⛔ 기존 행 220은 그대로 둔다.');
INSERT INTO player_status VALUES(253,210,'2026-09-19','injury','Wrist injury','Doubtful','2026-08-04','fotmob.com/api/data (player 156008, scripts/collect_fotmob_players.py, 2026-09-19 수집)','⚠️ 스냅샷이다 — pulled 시점의 상태이고 복귀 예상은 소스 추정이다. 부상은 이적 등급을 바꾸지 않는다(obs#272) — 성사 확률·구조 비용 축이다.');
