INSERT INTO player_status VALUES(256,19,'2026-09-19','injury','등 통증','스퍼스전 결장 확정 · 기간 미제시. ⚠️ 하프타임 절뚝임 서술과 부위 충돌 미해소','2026-09-18','avfc.co.uk 에메리 09-18 프리매치 회견 · Rotowire (D+3 수집)','MEDIUM — 감독 발언은 등, 현장 서술은 하지. 구단 공식 진단 0건');
