INSERT INTO player_status VALUES(259,59,'2026-09-20','injury','doubt','코번트리전 이상으로 스퍼스전 명단 제외. 휴식기 후 복귀 예상(Tanswell 2026-09-19). ⚠️ 구단 공식 부위·기간 발표 없음.','2026-09-19','reports/match-watch/2026-09-19-avl-tottenham.D1-findings.md(병렬 세션 인계 메모 — 흡수 후 삭제) · avfc.co.uk 에메리 회견 본문 · 에메리 D-1 회견 · Jacob Tanswell 2026-09-19','HIGH(결장 사실) / 복귀 시점은 예상치 — 구단 확정 발표 아님');
INSERT INTO player_status VALUES(260,61,'2026-09-20','injury','return_expected','에메리 D-1 회견 원문 「expected to return to full training during the international break」(휴식기 중 정식 훈련 복귀 예상).','2026-09-19','reports/match-watch/2026-09-19-avl-tottenham.D1-findings.md(흡수 후 삭제) · 에메리 D-1 회견','HIGH(결장 사실) / 복귀 시점은 예상치');
